// qb_act: activation supply of qc18bacc (ARCH v1.2 RTL plan R2).  Binary-map SRAM lines -> line buffer (registers)
// -> patch network (hw/rtl/qb_act_net.sv, generated by hw/tb/gen_act.py) -> qb_core act port, plus the item
// sequence of one array pass (tiles x channel tiles x [planes x] chunks, int8 all-zero-patch skip as
// compile/dataflow.py) as item descriptors for the weight / control path.
//
// Map layout (compile/layout.py): row (plane * H + y) = 4 lines of 512 b at line c_base + 4 row + q, chunk-major
// inside the row.  Read port: m_ren / m_ra are registers (macro boundary), the macro (rf_2p, 1-cycle read) returns
// m_q one edge after it samples them, and m_q is registered here (rdq) before the line-buffer write: issue i ->
// LB write at the end of cycle i + 3.
//
// Pipeline of an item issued (sequencer decision) in cycle i:
//   i      issue: chunk / plane / tile decided, sel1 (S1 select one-hot) and sel2 (cfg one-hot) registered at E_i
//   i + 1  S1 <- chunk slice of the LB (sel1) ; descriptor d_* valid (registered)
//   i + 2  act_d = S2 network (sel2) -> act register
//   i + 3  act valid (+ ACT_PIPE extra register stages: fanout to the 8 PE columns of a row)
//   descriptor (d_*) leads the act (a_*) by 2 + ACT_PIPE cycles; qb_core wants codes / ctl 1 cycle before the act.
// Window shifts (tile / plane-block advance) are applied one cycle after the last issue of the old window (vbp
// tracks vb), so the last item's S1 still reads the old window.
module qb_act #(parameter int ACT_PIPE = 1) (
    input  logic          clk,
    input  logic          rst_n,
    // pass command (held stable while busy)
    input  logic          start,
    input  logic [3:0]    c_cfg,      // 0, 2..10 (gen_act.py table; cfg 1 = odd tiles of cfg 0, internal)
    input  logic [4:0]    c_nchunk,   // 3x3: Cin / 32 (1..16); 1x1: 1
    input  logic [3:0]    c_nct,      // channel tiles Cout / 64 (1..8)
    input  logic [6:0]    c_ntile,    // pixel tiles (1..64)
    input  logic          c_int8,     // 8 bit-planes, plane-major, all-zero-patch skip (cfg 8 / 9 / 10)
    input  logic          c_stem,     // stem: chunk h = planes 4h..4h+3 (plane field 4h, g3n on h = 1)
    input  logic [8:0]    c_base,     // line address of row 0
    output logic          busy,
    output logic          done,       // 1-cycle pulse after the last act word
    // map read port
    output logic          m_ren,
    output logic [8:0]    m_ra,
    input  logic [511:0]  m_q,
    // item descriptor (valid on d_vld; d_eot marks the end of a (tile, channel tile), on the last item or alone)
    output logic          d_vld, d_first, d_eot, d_neg, d_stem, d_g3n,
    output logic [2:0]    d_plane,
    output logic [3:0]    d_chunk,
    output logic [2:0]    d_ct,
    output logic [5:0]    d_tile,
    // act port (same fields, 2 + ACT_PIPE cycles later)
    output logic [4607:0] act,
    output logic          a_vld, a_first, a_eot, a_neg, a_stem, a_g3n,
    output logic [2:0]    a_plane,
    output logic [3:0]    a_chunk,
    output logic [2:0]    a_ct,
    output logic [5:0]    a_tile
);
    localparam int DW = 1 + 1 + 1 + 1 + 1 + 1 + 3 + 4 + 3 + 6;     // descriptor bits

    // ---------------------------------------------------------------- per-cfg constants
    logic [5:0] H;  logic [3:0] K;  logic padL, even, k1;  logic [2:0] adv;  logic [3:0] R;  logic [1:0] wcls;
    always_comb begin
        H = 6'd32; K = 4'd3; padL = 1'b1; even = 1'b0; k1 = 1'b0; adv = 3'd1; R = 4'd8; wcls = 2'd0;
        unique case (c_cfg)
            4'd0:  begin H = 32; K = 3; padL = 1; adv = 1; wcls = 0; end           // adv applied on odd tiles
            4'd2:  begin H = 32; K = 3; padL = 1; adv = 2; wcls = 0; end
            4'd3:  begin H = 32; K = 2; padL = 0; adv = 2; wcls = 0; even = 1; k1 = 1; end
            4'd4:  begin H = 16; K = 3; padL = 1; adv = 1; wcls = 1; end
            4'd5:  begin H = 16; K = 5; padL = 1; adv = 4; wcls = 1; end
            4'd6:  begin H = 16; K = 4; padL = 0; adv = 4; wcls = 1; even = 1; k1 = 1; end
            4'd7:  begin H = 8;  K = 4; padL = 1; adv = 2; wcls = 2; end
            4'd8:  begin H = 8;  K = 8; padL = 0; adv = 0; wcls = 2; R = 8; end
            4'd9:  begin H = 8;  K = 8; padL = 0; adv = 0; wcls = 2; R = 8; even = 1; k1 = 1; end
            default: begin H = 4; K = 4; padL = 0; adv = 0; wcls = 3; R = 4; end   // 10
        endcase
    end
    wire [9:0] vtot = c_int8 ? {c_nct, 3'b000} * {6'd0, R} : {4'd0, H} + {8'd0, padL, 1'b0};

    // ---------------------------------------------------------------- state
    typedef enum logic [2:0] {S_IDLE, S_BIN, S_WAIT, S_FLAG, S_ITER, S_CTEND, S_FIN} st_t;
    st_t st;
    logic [9:0]  vb, vbp, vl, vdone;
    logic [1:0]  lq;
    logic [6:0]  tile;
    logic [3:0]  ct;
    logic [4:0]  g;
    logic [2:0]  pl;
    logic [15:0] mask;
    logic        any;
    logic [3:0]  fin_cnt;

    logic [16383:0] lbf;                               // line buffer, slot s = bits 2048 s ..

    // ---------------------------------------------------------------- loader (virtual rows vl, 4 quarters each)
    logic [9:0] iy_b;  logic [2:0] y8;  logic [2:0] p8;  logic [6:0] mrow;  logic l_pad, l_skip;
    always_comb begin
        iy_b = vl - {9'd0, padL};
        y8   = (R == 4) ? {1'b0, vl[1:0]} : vl[2:0];
        p8   = (R == 4) ? vl[4:2] : vl[5:3];
`ifdef QBA_MUT_PLANE
        if (c_int8) mrow = (p8 ^ 3'd1) * H[5:0] + {4'd0, y8};   // mutant: plane order
`else
        if (c_int8) mrow = p8 * H[5:0] + {4'd0, y8};
`endif
        else        mrow = iy_b[6:0];
        l_pad  = !c_int8 && (vl < {9'd0, padL} || iy_b >= {4'd0, H});
`ifdef QBA_MUT_PHASE
        l_skip = even && !(c_int8 ? y8[0] : iy_b[0]);      // mutant: 1x1 stride-2 row phase
`else
        l_skip = even && (c_int8 ? y8[0] : iy_b[0]);
`endif
    end
    wire l_go = (st != S_IDLE) && (st != S_FIN) && (vl < vtot) && (vl < vb + 10'd8);

    typedef struct packed { logic v; logic wr; logic zero; logic last; logic [1:0] q; logic [9:0] row; } ev_t;
    ev_t ev0, ev1, ev2;
    logic [511:0] rdq;
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            ev0 <= '0; ev1 <= '0; ev2 <= '0; m_ren <= 1'b0; m_ra <= '0; vl <= '0; lq <= '0;
        end else begin
            ev0 <= '0; m_ren <= 1'b0;
            if (start) begin vl <= '0; lq <= '0; end
            else if (l_go) begin
                if (l_skip) begin
                    ev0 <= '{v: 1'b1, wr: 1'b0, zero: 1'b0, last: 1'b1, q: 2'd0, row: vl};
                    vl  <= vl + 10'd1;
                end else begin
`ifdef QBA_MUT_PAD
                    ev0 <= '{v: 1'b1, wr: 1'b1, zero: 1'b0, last: (lq == 2'd3), q: lq, row: vl};  // mutant: padding
`else
                    ev0 <= '{v: 1'b1, wr: 1'b1, zero: l_pad, last: (lq == 2'd3), q: lq, row: vl};
`endif
                    m_ren <= !l_pad;
                    m_ra  <= c_base + {mrow, lq};
                    lq <= lq + 2'd1;
                    if (lq == 2'd3) vl <= vl + 10'd1;
                end
            end
            ev1 <= ev0;
            ev2 <= ev1;
        end
    always_ff @(posedge clk) rdq <= m_q;

    // ---------------------------------------------------------------- line buffer: shift (vb - vbp) + line write
    logic [2:0] shq;                                 // registered one-hot shift {4, 2, 1} = vb - vbp (timing)
    wire [9:0] wsl   = ev2.row - vb;                 // slot in post-shift coordinates
    qba_lb u_lb (.clk, .shq, .wr_en(ev2.v && ev2.wr), .wsl(wsl[2:0]), .wq(ev2.q), .wzero(ev2.zero), .rdq, .lbf);
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) vdone <= '0;
        else if (start) vdone <= '0;
        else if (ev2.v && ev2.last) vdone <= ev2.row + 10'd1;

    // ---------------------------------------------------------------- patch network + skip flags (qb_act_net.sv)
    localparam int NS1 = 192;
    logic [32:0]       sel1;
    logic [10:0]       sel2, sel2_1;
    logic [32*NS1-1:0] s1;
    logic [4607:0]     act_q;
    logic [7:0] f8;  logic f9;  logic [15:0] f10;
    qba_s1  u_s1  (.clk, .lb(lbf), .sel1, .s1);
    qba_s2  u_s2  (.clk, .s1, .sel2(sel2_1), .act(act_q));
    qba_flg u_flg (.clk, .lb(lbf), .f8, .f9, .f10);

    // ---------------------------------------------------------------- sequencer
    wire        bin_ready = vdone >= vb + {6'd0, K};
    wire        int_ready = bin_ready && (vb == vbp);
    wire [15:0] flags = (c_cfg == 4'd8) ? {8'd0, f8} : (c_cfg == 4'd9) ? {15'd0, f9} : f10;
    logic [15:0] lowbit;
    logic [3:0]  lowidx;
    always_comb begin
        lowidx = '0;
        for (int i = 15; i >= 0; i--) if (mask[i]) lowidx = 4'(i);
        lowbit = 16'd1 << lowidx;
    end
    // issue (combinational decision of this cycle)
    logic is_v, is_first, is_eot, is_zero;  logic [3:0] is_g;  logic [2:0] is_pl;
    always_comb begin
        is_v = 1'b0; is_first = 1'b0; is_eot = 1'b0; is_zero = 1'b0; is_g = g[3:0]; is_pl = pl;
        unique case (st)
            S_BIN:  if (bin_ready) begin
                        is_v = 1'b1; is_first = (g == 5'd0);
                        is_eot = (g == c_nchunk - 5'd1);
                    end
            S_ITER: if (mask != 16'd0) begin is_v = 1'b1; is_first = !any; is_g = lowidx; end
            S_CTEND: begin is_eot = 1'b1; if (!any) begin is_v = 1'b1; is_first = 1'b1; is_zero = 1'b1; is_g = '0;
                                                       is_pl = '0; end end
            default: ;
        endcase
    end
    wire last_tile = (tile == c_ntile - 7'd1);
    wire last_ct   = (ct == c_nct - 4'd1);
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) begin
            st <= S_IDLE; shq <= '0; vb <= '0; vbp <= '0; tile <= '0; ct <= '0; g <= '0; pl <= '0; mask <= '0; any <= 1'b0;
            fin_cnt <= '0;
        end else begin
            vbp <= vb;
            shq <= '0;
            unique case (st)
                S_IDLE: if (start) begin
                    vb <= '0; vbp <= '0; tile <= '0; ct <= '0; g <= '0; pl <= '0; any <= 1'b0;
                    st <= c_int8 ? S_WAIT : S_BIN;
                end
                S_BIN: if (bin_ready) begin
                    if (g != c_nchunk - 5'd1) g <= g + 5'd1;
                    else begin
                        g <= '0;
                        if (!last_ct) ct <= ct + 4'd1;
                        else begin
                            ct <= '0;
                            if (c_cfg != 4'd0 || tile[0]) begin
                                vb  <= vb + {7'd0, adv};
                                shq <= {adv == 3'd4, adv == 3'd2, adv == 3'd1};
                            end
                            if (last_tile) begin st <= S_FIN; fin_cnt <= '0; end
                            else tile <= tile + 7'd1;
                        end
                    end
                end
                S_WAIT: if (int_ready) st <= S_FLAG;
`ifdef QBA_MUT_SKIP
                S_FLAG: begin mask <= flags & ((16'd1 << c_nchunk) - 16'd1) & 16'h7fff; st <= S_ITER; end  // mutant
`else
                S_FLAG: begin mask <= flags & ((16'd1 << c_nchunk) - 16'd1); st <= S_ITER; end
`endif
                S_ITER: if (mask != 16'd0) begin mask <= mask & ~lowbit; any <= 1'b1; end
                        else begin
                            vb <= vb + {6'd0, R};
                            shq <= {R == 4'd4, 2'b00};                      // R = 8: whole window reloaded
                            if (pl != 3'd7) begin pl <= pl + 3'd1; st <= S_WAIT; end
                            else st <= S_CTEND;
                        end
                S_CTEND: begin
                    pl <= '0; any <= 1'b0;
                    if (last_ct) begin st <= S_FIN; fin_cnt <= '0; end
                    else begin ct <= ct + 4'd1; st <= S_WAIT; end
                end
                S_FIN: begin
                    fin_cnt <= fin_cnt + 4'd1;
                    if (fin_cnt == 4'(3 + ACT_PIPE)) st <= S_IDLE;
                end
                default: st <= S_IDLE;
            endcase
        end
    assign busy = st != S_IDLE;
    assign done = (st == S_FIN) && (fin_cnt == 4'(3 + ACT_PIPE));

    // select lines + descriptor (registered at issue)
    logic [DW-1:0] dsc;
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) begin sel1 <= '0; sel2 <= '0; dsc <= '0; end
        else begin
            sel1 <= '0;
            if (is_v && !is_zero) begin
                if (k1) sel1[c_cfg == 4'd3 ? 30 : c_cfg == 4'd6 ? 31 : 32] <= 1'b1;
                else    sel1[(wcls == 0 ? 0 : wcls == 1 ? 2 : wcls == 2 ? 6 : 14) + is_g] <= 1'b1;
            end
            sel2 <= '0;
            sel2[(c_cfg == 4'd0 && tile[0]) ? 4'd1 : c_cfg] <= 1'b1;
            dsc <= {is_v, is_first, is_eot,
                    c_int8 && !c_stem && is_pl == 3'd7 && !is_zero,               // neg
                    c_stem, c_stem && is_g == 4'd1,                                  // stem, g3n
                    c_int8 ? is_pl : (c_stem ? {is_g[0], 2'b00} : 3'd0),            // plane
                    is_g, ct[2:0], tile[5:0]};
        end
    assign {d_vld, d_first, d_eot, d_neg, d_stem, d_g3n, d_plane, d_chunk, d_ct, d_tile} = dsc;

    // act pipeline
    logic [DW-1:0] dsc1, dsc2;
    always_ff @(posedge clk or negedge rst_n)
        if (!rst_n) begin dsc1 <= '0; dsc2 <= '0; sel2_1 <= '0; end
        else begin dsc1 <= dsc; dsc2 <= dsc1; sel2_1 <= sel2; end
    logic [DW-1:0] dscp [ACT_PIPE + 1];
    logic [4607:0] actp [ACT_PIPE + 1];
    assign dscp[0] = dsc2;
    assign actp[0] = act_q;
    for (genvar k = 0; k < ACT_PIPE; k++) begin : g_pipe
        always_ff @(posedge clk or negedge rst_n)
            if (!rst_n) dscp[k + 1] <= '0; else dscp[k + 1] <= dscp[k];
        qba_areg u_ap (.clk, .d(actp[k]), .q(actp[k + 1]));
    end
    assign act = actp[ACT_PIPE];
    assign {a_vld, a_first, a_eot, a_neg, a_stem, a_g3n, a_plane, a_chunk, a_ct, a_tile} = dscp[ACT_PIPE];
endmodule

// line buffer: 8 slots x 2048 b of flops; per edge: shift by shq (one-hot 1 / 2 / 4 slots toward slot 0, else hold)
// then write one 512-b quarter wq of slot wsl (post-shift coordinates) with the registered macro line (or zeros).
module qba_lb (
    input  logic          clk,
    input  logic [2:0]    shq,
    input  logic          wr_en,
    input  logic [2:0]    wsl,
    input  logic [1:0]    wq,
    input  logic          wzero,
    input  logic [511:0]  rdq,
    output logic [16383:0] lbf);
    logic [2047:0] lb [8];
    always_comb for (int s = 0; s < 8; s++) lbf[2048 * s +: 2048] = lb[s];
    always_ff @(posedge clk) begin
        for (int s = 0; s < 8; s++) begin
            logic [2047:0] nx;
            nx = lb[s];
            if (shq[0] && s + 1 < 8) nx = lb[(s + 1) % 8];
            if (shq[1] && s + 2 < 8) nx = lb[(s + 2) % 8];
            if (shq[2] && s + 4 < 8) nx = lb[(s + 4) % 8];
            if (wr_en && wsl == 3'(s)) nx[512 * wq +: 512] = wzero ? 512'd0 : rdq;
            lb[s] <= nx;
        end
    end
endmodule

module qba_areg (input logic clk, input logic [4607:0] d, output logic [4607:0] q);
    always_ff @(posedge clk) q <= d;
endmodule
